class Solution {
public:
    int minSubarray(vector<int>& nums, int p) {
        long long total = 0;
        for (int x : nums) total += x;
        long long r = total % p;
        if (r == 0) return 0;

        int n = nums.size();
        int ans = n;
        unordered_map<long long, int> last;
        last[0] = 0;

        long long prefix = 0;
        for (int i = 0; i < n; i++) {
            prefix += nums[i];
            long long cur = prefix % p;
            long long target = ((cur - r) % p + p) % p;
            auto it = last.find(target);
            if (it != last.end()) {
                int len = i + 1 - it->second;
                if (len < ans) ans = len;
            }
            last[cur] = i + 1;
        }

        return ans == n ? -1 : ans;
    }
};
